import{_ as t,c as s,o as p,ah as o,ao as a,ap as i}from"./chunks/framework.Dq2_gudl.js";const v=JSON.parse('{"title":"悲しんでもいいのです — あなたの涙を、神は瓶に集めておられる","description":"ペットを亡くして泣くことは、信仰が弱いことではありません。詩篇は、神が私たちの涙を瓶に集め、書に記されると言います。","frontmatter":{"title":"悲しんでもいいのです — あなたの涙を、神は瓶に集めておられる","description":"ペットを亡くして泣くことは、信仰が弱いことではありません。詩篇は、神が私たちの涙を瓶に集め、書に記されると言います。"},"headers":[],"relativePath":"ja/pets-in-heaven/permission-to-grieve.md","filePath":"ja/pets-in-heaven/permission-to-grieve.md"}'),n={name:"ja/pets-in-heaven/permission-to-grieve.md"};function l(c,e,r,h,m,d){return p(),s("div",null,[...e[0]||(e[0]=[o('<div class="pl-quote"><p>「もう何か月も経つのに、まだ泣いています。私が強くないのでしょうか。信仰が小さいのでしょうか」</p><p class="pl-quote-soft">聖書は涙を、失敗の証拠として扱ったことは一度もありません。まったく逆です。</p></div><section class="pl-section"><h2>1. 神は涙を瓶に集めておられる</h2><blockquote><p><strong>詩篇 56:8</strong></p><p>&quot;Thou tellest my wanderings: put thou my tears into thy bottle: are they not in thy book?&quot;</p></blockquote><p>ダビデは深い苦しみの中でこれを書きました。彼は自分の涙を瓶に納め、書に記してほしいと願います。古代において、涙の瓶はとても貴重なコレクションで、「この人はこのことで泣いた」という証しでした。</p><p>つまりこういうことです。<strong>あなたの涙は、流れて消えてしまうものではありません。</strong>一滴も無駄になりません。その子のために流した涙のすべてが、集められています。記されています。</p><p>「泣きすぎているのかな」と思ったとき、思い出してください。神にとって、それは雑音ではなく記録です。</p></section><section class="pl-section"><h2>2. 神は心の砕かれた者に近づかれる — 叱られない</h2><blockquote><p><strong>詩篇 34:18</strong></p><p>&quot;The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit.&quot;</p></blockquote><blockquote><p><strong>詩篇 147:3</strong></p><p>&quot;He healeth the broken in heart, and bindeth up their wounds.&quot;</p></blockquote><p>動詞に注目してください。<em>近づかれる</em>。<em>いやされる</em>。<em>包まれる</em>。神が悲しむ人に対して最初にされることは、しっかりしなさいと求めることではなく、そばに来てくださることです。</p><p>イエスも短いひと言を残されました。</p><blockquote><p><strong>マタイの福音書 5:4</strong></p><p>&quot;Blessed are they that mourn: for they shall be comforted.&quot;</p></blockquote><p>「悲しむ者は幸いです。」悲しむ人は叱られるのではなく、幸いだと宣言されます。慰めが来るからです。「元気を出しなさい」ではなく、「あなたは慰められる」です。</p></section><section class="pl-section"><h2>3. 悲しみは愛の反対ではなく、愛が続いていること</h2><p>一度も愛したことのないもののために、私たちは泣きません。これほど痛むのは、あなたがたの間に本当に愛があったからです。</p><p>神は、失うことに泣く存在として私たちを造られました。イエスご自身も、ラザロの墓の前で泣かれました（ヨハネの福音書 11:35）。数分後に彼をよみがえらせると知りながら、それでも泣かれました。</p><p>だから、涙を誰かに謝る必要はありません。信仰が足りないのではありません。愛の中で傷ついただけです。</p><p class="pl-quote-soft">よろしければ、こう祈ってみてください。</p></section><div class="pl-quote"><p>「主よ、私が何度泣いたかをご存じです。<br>早く元気になれと急かさず、一滴一滴を瓶に納めてくださって感謝します。<br>心の砕かれた者に近づかれるように、私にも近づいてください。<br>私をいやし、恋しいあの子をどうか顧みてください。<br>今日は強くなりたくありません。ただ、あなたに抱かれていたいのです。アーメン。」</p></div><section class="pl-section"><h2>今、自分のためにできる4つのこと</h2><div class="pl-moment-grid"><div class="pl-moment"><span class="pl-moment-icon">🌊</span><h3>感情のピークで決めない</h3><p>悲しみの波は過ぎていきます。いちばん辛い瞬間は、次の5分を生き延びれば十分です。ほかのことは何も決めないでください。</p></div><div class="pl-moment"><span class="pl-moment-icon">🍽️</span><h3>まず身体をいたわる</h3><p>水を飲む。何か食べる。少し眠る。悲嘆は身体を消耗させ、空腹の身体は心の痛みを強くします。</p></div><div class="pl-moment"><span class="pl-moment-icon">📝</span><h3>その子をノートに書く</h3><p>うまくなくて大丈夫です。起こし方、いちばん好きだった表情。ひとつ書いてみてください。恋しさに行き場所を与えます。</p></div><div class="pl-moment"><span class="pl-moment-icon">🤝</span><h3>本当に分かってくれる人を探す</h3><p>動物のために泣くことを誰もが分かるわけではありませんが、分かる人もいます。見つからなければ、書いてください。神は読めます。</p></div></div></section><section class="pl-section"><h2>あの日は来ます</h2><p>ヨハネの黙示録は、いつか神ご自身が私たちの目からすべての涙をぬぐい去り、もはや死もなく、悲しみも、叫びも、痛みもないと約束しています（ヨハネの黙示録 21:4）。その日、あなたはその子のために流した一滴一滴が、良い神に覚えられ、応えられていたことを知るでしょう。</p><p>それまでは、悲しむことを自分に許してください。それもまた、その子を愛し続けるひとつの方法です。</p><p><a href="/ja/pets-in-heaven/">← Pets in Heaven に戻る</a> ｜ 最初の記事：<a href="/ja/pets-in-heaven/will-i-see-my-pet-again">また会えるのでしょうか？</a></p></section><div class="pl-cta"><h2>今日は、ひとことで十分です。</h2><p>PetLoss にはガイド付きジャーナルと、最も重い瞬間に足場となることばを届ける SOS の伴走があります。アカウント不要、アップロードなし、完全オフライン。</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">App Store でダウンロード</a></div><div class="pl-bible"><h3>みことばが、これからも寄り添うように</h3><p>この記事の聖句はすべて聖書から引用しています。虹の聖書ウィジェットなら、いつでも聖書を読み、毎日の聖句ウィジェットを設定できます。会いたい日に、小さな灯りとなりますように。</p><div class="pl-bible-shots"><figure><img src="'+a+'" alt="虹の聖書ウィジェット — 2 テモテ 2:13" loading="lazy"><figcaption>ホーム画面に毎日の聖句</figcaption></figure><figure><img src="'+i+'" alt="虹の聖書 — 天国にいるペット トピック、マタイ 10:29-31" loading="lazy"><figcaption>「天国にいるペット」テーマで聖書を</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">App Storeで虹の聖書ウィジェットを入手</a></div>',9)])])}const g=t(n,[["render",l]]);export{v as __pageData,g as default};
